Here is an example of a lambda function in Go for handling file uploads to S3 over HTTP:

```go
package main

import (
	"bytes"
	"context"
	"fmt"
	"io"
	"net/http"
	"os"

	"github.com/aws/aws-lambda-go/events"
	"github.com/aws/aws-lambda-go/lambda"
	"github.com/aws/aws-sdk-go/aws"
	"github.com/aws/aws-sdk-go/aws/session"
	"github.com/aws/aws-sdk-go/service/s3"
)

func uploadFileToS3(bucketName, fileName string, file io.Reader) error {
	sess := session.Must(session.NewSessionWithOptions(session.Options{
		SharedConfigState: session.SharedConfigEnable,
	}))

	svc := s3.New(sess)

	_, err := svc.PutObject(&s3.PutObjectInput{
		Bucket: aws.String(bucketName),
		Key:    aws.String(fileName),
		Body:   file,
	})

	if err != nil {
		return err
	}

	return nil
}

func handler(ctx context.Context, request events.APIGatewayProxyRequest) (events.APIGatewayProxyResponse, error) {
	file, ok := request.MultiValueHeaders["file"]
	if !ok {
		return events.APIGatewayProxyResponse{StatusCode: http.StatusBadRequest, Body: "No file provided"}, nil
	}

	fileName := request.QueryStringParameters["file_name"]
	bucketName := os.Getenv("S3_BUCKET_NAME")

	err := uploadFileToS3(bucketName, fileName, bytes.NewReader([]byte(file[0])))

	if err != nil {
		return events.APIGatewayProxyResponse{StatusCode: http.StatusInternalServerError, Body: fmt.Sprintf("Error uploading file: %v", err)}, nil
	}

	return events.APIGatewayProxyResponse{StatusCode: http.StatusOK, Body: "File uploaded successfully"}, nil
}

func main() {
	lambda.Start(handler)
}
```

In this example, the lambda function takes in an HTTP request with a file in the `file` header and a `file_name` query parameter. It uploads the file to the specified S3 bucket and returns a response indicating whether the upload was successful or not. Make sure to replace `S3_BUCKET_NAME` with the name of your S3 bucket.

